149	/* Tác vụ đọc nút bấm PA0 và gửi thông điệp vào Queues */
150	static void vTaskButton(void *pvParameters)
151	{
152	    (void)pvParameters;
153	    uint8_t prev_state = 0;
154	
155	    for (;;) {
156	        uint8_t state = (GPIOA->IDR & (1UL << BUTTON_PIN)) ? 1 : 0;
157	        if (state && !prev_state) {
158	            uint32_t msg = 1;
159	            if (xButtonQueue != NULL) {
160	                xQueueSend(xButtonQueue, &msg, 0);
161	            }
162	            if (xUIQueue != NULL) {
163	                xQueueSend(xUIQueue, &msg, 0);
164	            }
165	        }
166	        prev_state = state;
167	        vTaskDelay(pdMS_TO_TICKS(30)); /* Lọc rung nút bấm (debounce) */
168	    }
169	}
170	
171	/* Task 3: Chờ tín hiệu từ Queue để đổi trạng thái LED3 (PD5) */
172	static void vTaskLED3(void *pvParameters)
173	{
174	    (void)pvParameters;
175	    uint32_t rx_msg = 0;
176	    uint8_t led_state = 0;
177	
178	    for (;;) {
179	        if (xQueueReceive(xButtonQueue, &rx_msg, portMAX_DELAY) == pdPASS) {
180	            led_state = !led_state;
181	            if (led_state) {
182	                GPIOD->BSRR = (1UL << (LED3_PIN + 16)); /* Bật LED3 */
183	            } else {
184	                GPIOD->BSRR = (1UL << LED3_PIN);        /* Tắt LED3 */
185	            }
186	        }
187	    }
188	}
189	
190	/* Task 4: Giám sát hệ thống qua LED4 (PK3) - nhịp tim định kỳ */
191	static void vTaskMonitor(void *pvParameters)
192	{
193	    (void)pvParameters;
194	    for (;;) {
195	        GPIOK->BSRR = (1UL << (LED4_PIN + 16)); /* Bật LED4 */
196	        vTaskDelay(pdMS_TO_TICKS(100));
197	        GPIOK->BSRR = (1UL << LED4_PIN);        /* Tắt LED4 */
198	        vTaskDelay(pdMS_TO_TICKS(1900));
199	    }
200	}
201	
202	/* Task 5: Quản lý hiển thị LCD DSI OTM8009A và cập nhật giao diện */
203	static void vTaskLCD(void *pvParameters)
204	{
205	    (void)pvParameters;
206	    uint32_t rx_msg = 0;
207	
208	    /* Khởi tạo SDRAM và màn hình LCD DSI */
209	    UI_Init();
210	
211	    /* Khởi tạo cảm ứng điện dung qua I2C */
212	    Touch_Init();
213	
214	    uint8_t touch_was_pressed = 0;
215	
216	    for (;;) {
217	        /* Chờ tín hiệu từ nút bấm vật lý PA0 (timeout 40ms để quét cảm ứng) */
218	        if (xQueueReceive(xUIQueue, &rx_msg, pdMS_TO_TICKS(40)) == pdPASS) {
219	            UI_ToggleScreen();
220	        }
221	
222	        /* Quét điểm chạm trên màn hình cảm ứng */
223	        uint16_t tx = 0, ty = 0;
224	        if (Touch_Read(&tx, &ty)) {
225	            if (!touch_was_pressed) {
226	                UI_HandleTouch(tx, ty);
227	                touch_was_pressed = 1;
228	            }
229	        } else {
230	            touch_was_pressed = 0;
231	        }
232	    }
233	}
