235	int main(void)
236	{
237	    prvSetupHardware();
238	
239	    /* Tạo queue chứa sự kiện nút bấm */
240	    xButtonQueue = xQueueCreate(4, sizeof(uint32_t));
241	    xUIQueue     = xQueueCreate(4, sizeof(uint32_t));
242	
243	    /* Tạo các tác vụ ứng dụng LED, nút bấm và hiển thị LCD */
244	    xTaskCreate(vTaskLED1,    "LED1_1000ms", configMINIMAL_STACK_SIZE,       NULL, tskIDLE_PRIORITY + 1, NULL);
245	    xTaskCreate(vTaskLED2,    "LED2_400ms",  configMINIMAL_STACK_SIZE,       NULL, tskIDLE_PRIORITY + 1, NULL);
246	    xTaskCreate(vTaskButton,  "BtnPoll",     configMINIMAL_STACK_SIZE,       NULL, tskIDLE_PRIORITY + 2, NULL);
247	    xTaskCreate(vTaskLED3,    "LED3_Queue",  configMINIMAL_STACK_SIZE,       NULL, tskIDLE_PRIORITY + 1, NULL);
248	    xTaskCreate(vTaskMonitor, "Monitor",     configMINIMAL_STACK_SIZE,       NULL, tskIDLE_PRIORITY + 1, NULL);
249	    xTaskCreate(vTaskLCD,      "LCD_Task",    configMINIMAL_STACK_SIZE * 4,   NULL, tskIDLE_PRIORITY + 1, NULL);
250	
251	    /* Bắt đầu FreeRTOS scheduler */
252	    vTaskStartScheduler();
253	
254	    /* Không bao giờ tới đây */
255	    for (;;);
256	    return 0;
257	}

