72	void Default_Handler(void)
73	{
74	    while (1);
75	}

 1	/* Linker script for STM32F469NIH6
 2	 * Flash: 2048K at 0x08000000 (anh cho, chưa có tài liệu)
 3	 * RAM: 320K at 0x20000000 (anh cho, chưa có tài liệu)
 4	 */
 5	
 6	ENTRY(Reset_Handler)
 7	
 8	MEMORY
 9	{
10	    FLASH (rx)      : ORIGIN = 0x08000000, LENGTH = 2048K
11	    RAM (xrw)       : ORIGIN = 0x20000000, LENGTH = 320K
12	}
13	
14	_estack = ORIGIN(RAM) + LENGTH(RAM);
15	
16	_Min_Heap_Size = 0x200;      /* Required amount of heap */
17	_Min_Stack_Size = 0x800;     /* Required amount of stack */
18	
19	SECTIONS
20	{
21	    .isr_vector :
22	    {
23	        . = ALIGN(4);
24	        KEEP(*(.isr_vector))
25	        . = ALIGN(4);
26	    } >FLASH
27	
28	    .text :
29	    {
30	        . = ALIGN(4);
31	        *(.text)
32	        *(.text*)
33	        *(.glue_7)
34	        *(.glue_7t)
35	        *(.eh_frame)
36	
37	        KEEP (*(.init))
38	        KEEP (*(.fini))
39	
40	        . = ALIGN(4);
41	        _etext = .;
42	    } >FLASH
43	
44	    .rodata :
45	    {
46	        . = ALIGN(4);
47	        *(.rodata)
48	        *(.rodata*)
49	        . = ALIGN(4);
50	    } >FLASH
51	
52	    _sidata = LOADADDR(.data);
53	
54	    .data :
55	    {
56	        . = ALIGN(4);
57	        _sdata = .;
58	        *(.data)
59	        *(.data*)
60	        . = ALIGN(4);
61	        _edata = .;
62	    } >RAM AT> FLASH
63	
64	    .bss :
65	    {
66	        . = ALIGN(4);
67	        _sbss = .;
68	        __bss_start__ = _sbss;
69	        *(.bss)
70	        *(.bss*)
71	        *(COMMON)
72	        . = ALIGN(4);
73	        _ebss = .;
74	        __bss_end__ = _ebss;
75	    } >RAM
76	
77	    ._user_heap_stack :
78	    {
79	        . = ALIGN(8);
80	        PROVIDE ( end = . );
81	        PROVIDE ( _end = . );
82	        . = . + _Min_Heap_Size;
83	        . = . + _Min_Stack_Size;
84	        . = ALIGN(8);
85	    } >RAM
86	
87	    /DISCARD/ :
88	    {
89	        *(.note*)
90	        *(.comment*)
91	        *(.ARM.attributes)
92	    }
93	}

